defmodule Tuist.OpenGraph.ProjectImage do
  @moduledoc """
  Renders the social card used by public project pages.

  The layout is the Figma "Project cards" design (1920x1080, near-black
  ground): the project slug as a small eyebrow, the page title and a
  dot-separated subtitle top-left, the Tuist mark and wordmark bottom-left,
  and an optional status badge bottom-right. It mirrors the docs card so the
  dashboard and documentation share one family of link previews.

  The card intentionally uses self-contained HTML, fonts, and images so the
  headless browser does not depend on the application or object storage being
  reachable while it captures the image. The footer's mark and wordmark are
  the design's own outlines, inlined as SVG so they never depend on a font.
  """
  use Phoenix.Component

  alias Phoenix.HTML.Safe

  # Two lines of the 144px title fit between the eyebrow and the footer at
  # the 1768px content width once the subtitle is accounted for.
  @max_title_length 44
  @max_subtitle_length 110
  @subtitle_separator " · "

  attr :title, :string, required: true
  attr :project, :string, required: true
  attr :subtitle, :string, default: nil
  attr :badge, :string, default: nil
  attr :font_data_uri, :string, required: true

  def card(assigns) do
    assigns =
      assigns
      |> assign(:title_text, truncate(assigns.title, @max_title_length))
      |> assign(:subtitle_parts, subtitle_parts(assigns.subtitle))
      |> assign(:badge_status, badge_status(assigns.badge))
      |> assign(:badge_label, badge_label(assigns.badge))

    ~H"""
    <html>
      <head>
        <meta charset="utf-8" />
        <style>
          @font-face {
            font-family: 'Inter Variable';
            font-style: normal;
            font-weight: 100 900;
            src: url(<%= @font_data_uri %>) format('woff2');
          }
          /* Hex rather than Noora tokens: headless Chrome does not resolve
             oklch() reliably here. #0E0E0E is the near-black ground,
             #FDFDFD the primary label, #C9CCCF the secondary one. */
          * { margin: 0; padding: 0; box-sizing: border-box; }
          html, body {
            width: 1920px;
            height: 1080px;
            overflow: hidden;
            font-family: 'Inter Variable', sans-serif;
            color-scheme: dark;
            background: #0E0E0E;
          }
          /* Anchored to the subtitle's resting place rather than the top, so
             a title that wraps onto a second line pushes the block up and
             keeps the subtitle clear of the footer. */
          .content {
            position: absolute;
            left: 76px;
            bottom: 384px;
            width: 1768px;
            display: flex;
            flex-direction: column;
          }
          /* The eyebrow, subtitle and badge truncate with an ellipsis, which
             needs overflow: hidden. Their line boxes equal the font size, so
             each clipping box gets vertical padding, cancelled by negative
             margins, to leave room for ascenders and descenders. */
          .project {
            padding: 12px 0 18px;
            margin: -12px 0 -18px;
            font-size: 64px;
            font-weight: 400;
            line-height: 64px;
            letter-spacing: -0.05em;
            color: #C9CCCF;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
          }
          .title {
            margin-top: 67px;
            font-size: 140px;
            font-weight: 400;
            line-height: 140px;
            letter-spacing: -0.05em;
            color: #FDFDFD;
            overflow-wrap: anywhere;
          }
          .subtitle {
            display: flex;
            align-items: center;
            gap: 31px;
            min-height: 64px;
            padding: 12px 0 18px;
            margin: 60px 0 -18px;
            font-size: 64px;
            font-weight: 400;
            line-height: 64px;
            letter-spacing: -0.045em;
            color: #C9CCCF;
            white-space: nowrap;
            overflow: hidden;
          }
          .subtitle span {
            padding: 12px 0 18px;
            margin: -12px 0 -18px;
            overflow: hidden;
            text-overflow: ellipsis;
          }
          .subtitle i {
            flex: none;
            width: 20px;
            height: 20px;
            border-radius: 50%;
            background: #C9CCCF;
          }
          .footer {
            position: absolute;
            inset: 0;
            width: 1920px;
            height: 1080px;
          }
          .badge {
            position: absolute;
            right: 79px;
            bottom: 82px;
            max-width: 760px;
            padding: 10px 0 16px;
            margin: -10px 0 -16px;
            font-size: 58px;
            font-weight: 400;
            line-height: 58px;
            letter-spacing: -0.05em;
            color: #FDFDFD;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
          }
          /* Noora's status badge (.noora-status-badge) in dark mode, scaled
             3.5x so it sits comfortably beside the footer wordmark: the
             4px/8px padding, 4px gap, 6px radius, 16px icon and the
             light-default border ring all scale together. Token values are
             the dark-mode results of tokens.css, written as hex. */
          .badge[data-status] {
            right: 76px;
            bottom: 70px;
            display: inline-flex;
            align-items: center;
            gap: 14px;
            margin: 0;
            padding: 14px 28px 14px 14px;
            border-radius: 21px;
            background: #0E0E0E;
            box-shadow:
              0 3.5px 3.5px 0 rgba(14,14,14, 0.3),
              0 0 0 3.5px rgba(113,113,113, 0.45),
              0 7px 10.5px 0 rgba(0, 0, 0, 0.3);
            font-size: 42px;
            font-weight: 500;
            line-height: 56px;
            letter-spacing: 0;
            color: #FDFDFD;
            overflow: visible;
          }
          .badge[data-status="disabled"] { color: #A4A4A4; }
          .badge [data-part="icon"] {
            display: inline-flex;
            flex: none;
            width: 56px;
            height: 56px;
          }
          .badge [data-part="icon"] svg { width: 56px; height: 56px; }
          .badge [data-part="label"] {
            overflow: hidden;
            text-overflow: ellipsis;
          }
          .badge[data-status="success"] [data-part="icon"] { color: #008C1C; }
          .badge[data-status="error"] [data-part="icon"] { color: #BC0000; }
          .badge[data-status="warning"] [data-part="icon"] { color: #F25F00; }
          .badge[data-status="attention"] [data-part="icon"] { color: #FFC100; }
          .badge[data-status="disabled"] [data-part="icon"] { color: #A4A4A4; }
          .badge[data-status="in_progress"] [data-part="icon"] { color: #D2D2D2; }
        </style>
      </head>
      <body>
        <div class="content">
          <div class="project">{@project}</div>
          <div class="title">{@title_text}</div>
          <div class="subtitle">
            <%= for {part, index} <- Enum.with_index(@subtitle_parts) do %>
              <i :if={index > 0}></i>
              <span>{part}</span>
            <% end %>
          </div>
        </div>
        <svg
          class="footer"
          viewBox="0 0 1920 1080"
          xmlns="http://www.w3.org/2000/svg"
          fill="none"
          aria-hidden="true"
        >
          <g clip-path="url(#project-card-mark)">
            <path
              d="M115.203 1010.2C115.164 1010.19 115.128 1010.17 115.09 1010.13C114.165 1009.34 113.38 1000.18 113.165 998.489C111.644 985.895 109.701 973.357 107.341 960.896C106.498 956.475 105.631 952.059 104.74 947.647C103.979 943.853 103.333 940.405 102.924 936.551C102.143 929.202 107.513 928.198 113.589 927.841C114.056 927.816 114.602 927.798 115.203 927.796C115.803 927.798 116.349 927.816 116.816 927.841C122.892 928.198 128.263 929.202 127.482 936.551C127.072 940.405 126.427 943.853 125.665 947.647C124.774 952.059 123.907 956.475 123.064 960.896C120.704 973.357 118.761 985.895 117.241 998.489C117.025 1000.18 116.24 1009.34 115.315 1010.13C115.277 1010.17 115.241 1010.19 115.203 1010.2Z"
              fill="#927AFF"
