              d="M91.896 936.499C94.6992 936.16 96.0133 938.263 96.9695 940.551C97.9444 942.881 98.7309 945.363 99.4697 947.782C100.38 950.737 101.247 953.706 102.07 956.688C105.853 970.151 108.982 983.793 111.445 997.565C111.823 999.657 112.188 1001.75 112.542 1003.85C112.865 1005.78 113.23 1007.88 113.25 1009.82C111.863 1008.91 111.061 1006.54 110.391 1005.01C109.735 1003.52 109.071 1002.03 108.399 1000.55C107.582 998.577 106.393 996.184 105.46 994.259C100.846 984.731 95.3759 975.649 89.1213 967.129C87.3714 964.73 85.5564 962.38 83.6786 960.082C82.0206 958.014 79.6514 955.341 78.7793 952.878C77.0721 948.059 81.7684 943.097 85.0738 940.195C86.9332 938.563 89.4132 936.901 91.896 936.499Z"
              fill="#927AFF"
