              d="M77.5502 962.54C78.376 962.476 79.1971 962.81 79.8611 963.283C81.5247 964.471 83.0764 966.071 84.465 967.557C94.7173 978.529 102.509 991.603 109.07 1005.09C109.856 1006.71 110.64 1008.35 111.286 1010.03C110.446 1009.62 109.759 1009.16 108.984 1008.65C106.975 1007.26 104.813 1005.53 102.88 1004.02C99.7759 1001.55 96.6418 999.122 93.4781 996.731C90.7859 994.712 88.0769 992.718 85.3521 990.746C80.2659 987.061 76.6489 985.01 74.9431 978.434C73.958 974.638 72.6087 963.847 77.5502 962.54Z"
