            <path
              d="M152.855 962.54C152.029 962.476 151.208 962.81 150.544 963.283C148.88 964.471 147.329 966.071 145.94 967.557C135.688 978.529 127.896 991.603 121.335 1005.09C120.549 1006.71 119.765 1008.35 119.119 1010.03C119.959 1009.62 120.646 1009.16 121.421 1008.65C123.43 1007.26 125.592 1005.53 127.525 1004.02C130.629 1001.55 133.763 999.122 136.927 996.731C139.619 994.712 142.328 992.718 145.053 990.746C150.139 987.061 153.756 985.01 155.462 978.434C156.447 974.638 157.796 963.847 152.855 962.54Z"
