            <path
              d="M138.509 936.499C135.706 936.16 134.392 938.263 133.436 940.551C132.461 942.881 131.674 945.363 130.935 947.782C130.025 950.737 129.158 953.706 128.335 956.688C124.552 970.151 121.423 983.793 118.96 997.565C118.582 999.657 118.217 1001.75 117.863 1003.85C117.54 1005.78 117.176 1007.88 117.155 1009.82C118.542 1008.91 119.345 1006.54 120.014 1005.01C120.67 1003.52 121.334 1002.03 122.006 1000.55C122.824 998.577 124.012 996.184 124.945 994.259C129.559 984.731 135.029 975.649 141.284 967.129C143.034 964.73 144.849 962.38 146.727 960.082C148.384 958.014 150.754 955.341 151.626 952.878C153.333 948.059 148.637 943.097 145.331 940.195C143.472 938.563 140.992 936.901 138.509 936.499Z"
