          <defs>
            <clipPath id="project-card-mark">
              <rect width="82.409" height="82.409" fill="white" transform="translate(74 927.796)" />
            </clipPath>
          </defs>
        </svg>
        <div :if={@badge} class="badge" data-status={@badge_status}>
          <span :if={@badge_status} data-part="icon"><.status_icon status={@badge_status} /></span>
          <span :if={@badge_status} data-part="label">{@badge_label}</span>
          <%= if is_nil(@badge_status) do %>
            {@badge_label}
          <% end %>
        </div>
      </body>
    </html>
    """
  end

  def render_html(opts) do
    fonts_dir = Keyword.fetch!(opts, :fonts_dir)

    assigns = %{
      __changed__: nil,
      title: Keyword.fetch!(opts, :title),
      project: Keyword.fetch!(opts, :project),
      subtitle: Keyword.get(opts, :subtitle),
      badge: Keyword.get(opts, :badge),
      font_data_uri: data_uri(Path.join(fonts_dir, "InterVariable.woff2"), "font/woff2")
    }

    "<!DOCTYPE html>" <>
      (assigns |> card() |> Safe.to_iodata() |> IO.iodata_to_binary())
  end

  attr :status, :string, required: true

  defp status_icon(%{status: "success"} = assigns) do
    ~H"""
