  # Pages pass the badge as display text, so the status is recognised from
  # the dashboard's own vocabulary; anything else stays a plain label.
  @badge_statuses %{
    "success" => "success",
    "succeeded" => "success",
    "passed" => "success",
    "completed" => "success",
    "complete" => "success",
    "enabled" => "success",
    "failure" => "error",
    "failed" => "error",
    "error" => "error",
    "errored" => "error",
    "crashed" => "error",
    "failed processing" => "error",
    "flaky" => "warning",
    "warning" => "warning",
    "lost" => "warning",
    "attention" => "attention",
    "needs attention" => "attention",
    "skipped" => "disabled",
    "cancelled" => "disabled",
    "canceled" => "disabled",
    "disabled" => "disabled",
    "expired" => "disabled",
    "processing" => "in_progress",
    "running" => "in_progress",
    "in progress" => "in_progress",
    "pending" => "in_progress",
    "queued" => "in_progress"
  }

  defp badge_status(nil), do: nil

  defp badge_status(badge) do
    key = badge |> badge_label() |> String.downcase()
    Map.get(@badge_statuses, key)
  end

  defp badge_label(nil), do: nil
  defp badge_label(badge), do: badge |> String.replace("_", " ") |> String.trim()

  defp data_uri(path, content_type) do
    "data:#{content_type};base64,#{path |> File.read!() |> Base.encode64()}"
  end

  # LiveViews join subtitle fragments with " · "; the card draws each
  # fragment itself with the design's dot between them.
  defp subtitle_parts(nil), do: []

  defp subtitle_parts(subtitle) do
    subtitle
    |> truncate(@max_subtitle_length)
    |> String.split(@subtitle_separator, trim: true)
    |> Enum.map(&String.trim/1)
    |> Enum.reject(&(&1 == ""))
  end

  defp truncate(nil, _max), do: ""

  defp truncate(text, max) do
    if String.length(text) > max do
      text |> String.slice(0, max) |> String.trim_trailing() |> Kernel.<>("...")
    else
      text
    end
  end
end
